/* ---- GRAFICA DI PROVA: rocce spaccate e cespuglio senza liane ---- */
GfxNew.rub=function(){
  const mkR=(b64,lw,lh,ax,ay)=>{const img=new Image(),[c,x]=mk(lw,lh),s={c,w:lw,h:lh,ax,ay,art:1};
    img.onload=()=>{x.clearRect(0,0,lw,lh);x.drawImage(img,0,0,lw,lh);
      const[c2,x2]=mk(lw,lh);x2.drawImage(c,0,0,lw,lh);x2.globalCompositeOperation='source-in';x2.fillStyle='#0e1c0a';x2.fillRect(0,0,lw,lh);s.sh=c2};
    img.src='data:image/webp;base64,'+b64;return s};
  SP.rubble=mkR("",74,51.6,37,49.6);
  SP.rubbleS=mkR("",50,26.3,25,24.6);
  SP.bush0=mkR("",62,57.4,31,56);
};
